 /* i4: slow but with friction */
 let hatch='';for(let i=0;i<4;i++){hatch+=TH_L(58,y[3]+62+i*6,66,y[3]+56+i*6,MAG,3)+TH_L(204,y[3]+62+i*6,212,y[3]+56+i*6,MAG,3)}
